function drawOrderSymbol(context,label){
 context.save();context.strokeStyle='#e5c789';context.fillStyle='#a78a51';context.lineWidth=3;context.lineCap='round';context.lineJoin='round';
 const line=(points,close=false,fill=false)=>{context.beginPath();points.forEach(([x,y],i)=>i?context.lineTo(x,y):context.moveTo(x,y));if(close)context.closePath();if(fill)context.fill();context.stroke()};
 if(/取消|拆除/.test(label)){line([[23,17],[57,49]]);line([[57,17],[23,49]])}
 else if(/警報/.test(label)){line([[23,44],[28,37],[28,24],[33,16],[47,16],[52,24],[52,37],[57,44]],true);line([[35,50],[45,50]]);line([[40,11],[40,16]])}
 else if(/停止|停戰/.test(label)){context.strokeRect(24,17,32,32);context.fillRect(30,23,20,20)}
 else if(/攻擊|發射/.test(label)){context.beginPath();context.arc(40,32,17,0,Math.PI*2);context.stroke();line([[40,8],[40,23]]);line([[40,41],[40,56]]);line([[16,32],[31,32]]);line([[49,32],[64,32]])}
 else if(/買|贈送/.test(label)){for(let i=0;i<3;i++){context.beginPath();context.ellipse(40,43-i*10,19,7,0,0,Math.PI*2);context.fill();context.stroke()}}
 else if(/卸載|起飛|返航|指令/.test(label)){const up=/起飛|返航/.test(label);line(up?[[40,49],[40,15],[27,28],[40,15],[53,28]]:[[40,14],[40,48],[27,35],[40,48],[53,35]]);line([[20,45],[20,54],[60,54],[60,45]])}
 else if(/補種/.test(label)){line([[40,53],[40,25]]);line([[40,37],[24,32],[20,19],[34,24],[40,37]],true,true);line([[40,29],[48,15],[62,12],[57,26],[40,29]],true,true)}
 else{line([[40,20],[28,15],[15,18],[15,48],[28,45],[40,50],[52,45],[65,48],[65,18],[52,15],[40,20]],true);line([[40,20],[40,50]]);line([[22,26],[32,25]]);line([[48,25],[58,26]]);line([[22,34],[32,33]]);line([[48,33],[58,34]])}
 context.restore();
}
const ROLE_TAG={5:'運輸',6:'戰船',7:'對空',8:'炸建築',9:'空運'};/* Helen：看到「傾轉旋翼機」不知道那就是運輸機；用功能字眼，奇幻的巨鷹、幼龍也講得通 */
function roleWords(type,owner=0){const tag=ROLE_TAG[type];if(!tag||!g)return [];const name=g.unitName(type,owner)||'';const cap=UNIT[type]?.capacity;const dup=type===5||type===9?/運輸|運兵|渡/.test(name):type===8?/轟炸/.test(name):name.includes(tag);const out=[];if(!dup)out.push(tag);if(cap)out.push('載 '+cap+' 人');return out}
function roleTag(type,owner=0){const w=roleWords(type,owner);return w.length?'（'+w.join('，')+'）':''}
function roleHint(type){const w=roleWords(type,0);return w.length?' · '+w.join('，'):''}
function iconButton(label,index,sub,action,disabled=false,badgeType=null){const b=document.createElement('button');b.className='order';b.disabled=disabled;b.title=label+' '+sub;const c=document.createElement('canvas');c.width=80;c.height=65;if(typeof index==='string'&&BUILDINGS[index]?.procedural)defenseIcon(c.getContext('2d'),index);else if(typeof index==='string'&&index.startsWith('plane:')){drawPlane(c.getContext('2d'),index.slice(6),40,34,1.1,1,g.playerColor(0))}else if(index!=null){const d=sprite(c.getContext('2d'),index,2,0,76,65);if(d&&badgeType)drawBadge(c.getContext('2d'),badgeType,d.x+d.w-9,d.y+9,1.1)}else drawOrderSymbol(c.getContext('2d'),label);const text=document.createElement('span');text.textContent=label;const small=document.createElement('small');small.textContent=sub;b.append(c,text,small);b.onclick=action;return b}
function costText(cost){return cost.map((n,i)=>n?MODES[g.mode].resources[i]+n:'').filter(Boolean).join(' ')}
function response(r){if(!r.ok)toast(r.error);paintUI(true)}
function victoryLine(){const truce=g.truce&&g.time<g.truce?'<span class="standing">休戰期剩 '+fmt(g.truce-g.time)+'，期間各國互不攻擊</span>':'';return truce+victoryLine2()}
function victoryLine2(){if(g.victory==='scenario'&&g.scenario){return '<span class="standing objectives"><b>'+(g.scenario.title||'劇情目標')+'</b>'+g.objectiveStatus().map(s=>'<br>'+(s.done?'✓':'◇')+' '+s.text+(s.progress?' <small>'+s.progress+'</small>':'')).join('')+(g.scenario.lose||[]).map(l=>'<br>✗ '+(l.text||(l.kind==='deadline'?l.minutes+' 分鐘內完成':'保護'+g.playerName(l.player)))).join('')+'</span>'}if(g.victory==='landmark'){const st=g.landmarkStatus();const mine=st.counts[g.players[0].team]||0;return '<span class="standing">需持有 '+st.need+'/'+st.total+' 座據點並守住 '+Math.round(g.holdSeconds/60)+' 分鐘'+(st.holdTeam!=null?' · 第'+st.holdTeam+'隊守住中，剩 '+fmt(st.holdLeft):'')+'</span>'}if(g.victory==='wonder'){const w=g.wonderCountdown;return '<span class="standing">'+(w?g.playerName(w.owner)+'的'+g.buildingName('wonder')+'倒數 '+fmt(Math.max(0,w.left)):'第三時代後建造'+g.buildingName('wonder')+'，完工後倒數 '+Math.round(BUILDINGS.wonder.countdown/60)+' 分鐘')+'</span>'}if(g.victory==='timed')return '<span class="standing">剩餘 '+fmt(Math.max(0,g.timeLimit-g.time))+' · 依資源、軍力、建築、科技計分</span>';return ''}
// 君主對話（Helen 2026-09-21）：引擎丟 speeches（誰、對誰、什麼事），這裡用 rulers.js 找君主、台詞與立繪，畫面左側顯示。
