function storage(){try{return globalThis.localStorage||null}catch{return null}}
function uiState(){return {cam:{x:cam.x,y:cam.y,z:cam.z},selected:selected.slice(),groups:JSON.parse(JSON.stringify(groups)),speed}}
function saveGame(slot,quiet=false){if(!gameStarted){if(!quiet)toast('尚未開始戰役');return false}if(g.over&&quiet)return false;const st=storage();if(!st){if(!quiet)toast('儲存失敗：瀏覽器不允許本機儲存');return false}try{const text=JSON.stringify(g.serialize(uiState()));st.setItem(SAVE_KEY+slot,text);if(st.getItem(SAVE_KEY+slot)!==text)throw new Error('寫入後讀回不一致');if(!quiet){toast((slot==='auto'?'自動存檔':'存檔 '+slot)+'完成（'+Math.round(text.length/1024)+' KB）');renderSaves()}return true}catch(err){const quota=err&&(err.name==='QuotaExceededError'||/quota/i.test(err.message||''));if(!quiet||nowMs()-(saveFailAt||0)>300000){saveFailAt=nowMs();toast('儲存失敗：'+(quota?'本機儲存空間不足，請刪除舊存檔':err.message));sound?.fx('error')}return false}}
function applyLoaded(data){const loaded=Game.load(WORLD,data);g=loaded;window.game=g;gameStarted=true;paused=false;resultShown=!!g.over;placing=null;orderMode=false;pendingOrder=null;autosaveAt=g.time;speed=data.ui?.speed||1;$('speed').textContent=speed+'×';$('pause').textContent='Ⅱ 暫停';groups=data.ui?.groups||{};selected=(data.ui?.selected||[]).filter(id=>g.get(id));terrainCache=null;miniCache=null;uiKey='';spokenSelection=selected.join(',');if(data.ui?.cam){cam.x=data.ui.cam.x;cam.y=data.ui.cam.y;cam.z=data.ui.cam.z}else home();$('resume').hidden=false;for(const d of document.querySelectorAll('dialog[open]'))d.close();paintUI(true);toast('已載入：'+saveLabel(data))}
function loadText(text){try{const data=JSON.parse(text);applyLoaded(data);sound?.unlock();return true}catch(err){toast('讀取失敗：'+(err instanceof SyntaxError?'檔案不是有效的存檔':err.message));sound?.fx('error');return false}}
function loadGame(slot){if(gameStarted&&g&&!g.over&&!confirm('目前的戰役會被覆蓋（可先存檔），確定載入？'))return false;const st=storage();if(!st){toast('讀取失敗：瀏覽器不允許本機儲存');return false}const text=st.getItem(SAVE_KEY+slot);if(!text){toast('這個存檔槽是空的');return false}return loadText(text)}
function renderSaves(){const box=$('saveSlots');if(!box)return;const st=storage();box.replaceChildren();for(const slot of ['auto','1','2','3']){const row=document.createElement('div');row.className='save-row';const label=document.createElement('span');let data=null;try{const text=st?.getItem(SAVE_KEY+slot);if(text)data=JSON.parse(text)}catch{}label.textContent=(slot==='auto'?'自動存檔':'存檔 '+slot)+'：'+(data?saveLabel(data):'（空）');const save=document.createElement('button');save.textContent='儲存';save.disabled=slot==='auto'||!gameStarted;save.onclick=()=>saveGame(slot);const load=document.createElement('button');load.textContent='載入';load.disabled=!data;load.onclick=()=>loadGame(slot);row.append(label,save,load);box.append(row)}}
function exportSave(){if(!gameStarted){toast('尚未開始戰役');return}try{const text=JSON.stringify(g.serialize(uiState()));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download='列國紀元_'+g.map+'_'+fmt(g.time).replace(':','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('已匯出 JSON（'+Math.round(text.length/1024)+' KB）')}catch(err){toast('匯出失敗：'+err.message)}}
$('saveMenu').onclick=()=>{renderSaves();$('saveDialog').showModal();keys.clear()};$('loadMenu').onclick=()=>{renderSaves();$('saveDialog').showModal()};$('closeSave').onclick=()=>$('saveDialog').close();$('exportSave').onclick=exportSave;$('importSave').onchange=e=>{const f=e.target.files?.[0];if(!f)return;f.text().then(loadText).finally(()=>{e.target.value=''})};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','SELECT'].includes(e.target.tagName))return;if(e.key==='F5'&&gameStarted){e.preventDefault();saveGame('1')}if(e.key==='F9'){e.preventDefault();loadGame('1')}});
window.nationsSave={save:saveGame,load:loadGame,loadText,render:renderSaves};

// Technology overview is read-only; jump to an owned research building to issue orders.
function renderTechTree(){const list=$('techList');list.replaceChildren();for(const [id,d] of Object.entries(TECHS)){const status=g.techStatus(g.human,id),card=document.createElement('article');card.className='tech-card '+(status.state||'locked');const title=document.createElement('h3');title.textContent=g.techName(id,0);const effect=document.createElement('p');effect.textContent=d.effect;const req=document.createElement('p');req.textContent='研究場所：'+g.buildingName(d.from)+' · '+MODES[g.mode].ages[d.age].name+(d.requires.length?' · 前置：'+d.requires.map(k=>g.techName(k,0)).join(' → '):'')+(d.buildings.length?' · 需有：'+d.buildings.map(k=>g.buildingName(k)).join('、'):'');const cost=document.createElement('p');const disc=g.techs[0].includes('printing')&&id!=='printing';cost.textContent=costText(g.techCost(0,id))+' · '+Math.round(d.time*(disc?.75:1))+'秒'+(disc?'（印刷術折扣）':'');const state=document.createElement('strong');state.textContent=status.ok?'可研究':status.error;card.append(title,effect,req,cost,state);const b=g.buildings.find(b=>b.owner===g.human&&b.type===d.from&&b.hp>0&&b.progress>=1);if(b&&gameStarted){const jump=document.createElement('button');jump.textContent='前往'+g.buildingName(d.from);jump.onclick=()=>{selected=[b.id];const c=g.center(b),p=iso(c.x,c.y);cam.x=p.x;cam.y=p.y-g.heightAt(c.x,c.y);$('techDialog').close();paintUI(true)};card.append(jump)}list.append(card)}}
$('techMenu').onclick=()=>{renderTechTree();$('techDialog').showModal();keys.clear()};$('closeTech').onclick=()=>$('techDialog').close();

// P3-E 盟友贈送視窗：選隊友、輸入四種資源整數，送出前由引擎驗證。
// 王與王的主動溝通（Helen 2026-09-21）：通訊方式依時代（使者／飛鴿／驛馬／電報／無線電／熱線／視訊／全像／水晶球）；送出後地圖上看得到在路上，回覆用立繪對話框。
let msgTarget=null;const MSG_KINDS=[['greet','問候・試探','看看對方態度，關係 +'],['threaten','威嚇・最後通牒','弱國可能退讓，關係 −'],['tribute','要求貢品','對方明顯較弱才會給黃金'],['gift','贈禮','關係大幅 +，資源由你出'],['peace','提議停戰','關係好比較容易答應'],['ally','提議結盟','要先停戰；共享視野'],['intel','打聽情報','問他跟誰交戰、跟誰停戰']];
function openMessage(id){if(!g||!g.players[id])return;msgTarget=id;const m=g.commsMedium(0);const name=g.playerName(id);$('msgTitle').textContent=m.icon+' '+m.name+' → '+name;const rel=g.relation(0,id);const relText=rel>=40?'友好':rel>=10?'尚可':rel>-10?'平淡':rel>-40?'冷淡':'敵視';let eta='';if(m.walk||m.speed){const a=g.bases[0],b=g.bases[id];eta='約 '+Math.ceil(RTS.distance(a,b)*(m.walk?1.3:1)/m.speed)+' 秒送達'+(m.intercept?'，途中若遇交戰勢力的部隊會被攔截':'，不會被攔截')}else eta='即時（約 '+(m.delay||2)+' 秒）';$('msgMeta').textContent='關係：'+relText+'（'+rel+'）・'+eta;const busy=g.couriers.some(c=>c.to===id);$('msgKinds').replaceChildren(...MSG_KINDS.filter(([k])=>!(k==='peace'&&g.lockTeams)&&!(k==='ally'&&g.lockTeams)).map(([k,t,d])=>{const b=document.createElement('button');b.innerHTML=t+'<small>'+d+'</small>';b.disabled=busy;b.onclick=()=>{if(k==='gift'){$('msgGift').hidden=false;$('msgKinds').hidden=true;return}sendMsg(k)};return b}));$('msgGift').hidden=true;$('msgKinds').hidden=false;$('msgGiftRows').replaceChildren(...MODES[g.mode].resources.map((n,i)=>{const l=document.createElement('label');l.innerHTML=n+'<input type="number" min="0" max="1000" step="10" value="0" data-res="'+i+'">';return l}));$('msgHint').textContent=busy?'上一封訊息還在路上，等回覆後再傳。':'選一種訊息送出；對方讀到後會用立繪回覆。';$('messageDialog').showModal()}
function sendMsg(kind,payload){if(msgTarget==null)return;const res=g.sendMessage(kind,msgTarget,payload);if(!res.ok){toast(res.error);return}$('messageDialog').close();const m=RTS.COMMS[res.courier.medium];toast(m.icon+' '+m.name+'已送出，約 '+res.courier.eta+' 秒');if(talkOn&&window.RULERS){const me=window.RULERS.resolve(g,0);const text=window.RULERS.sentLine(me,kind,Math.floor(g.time),{t:g.playerName(msgTarget)});if(me&&text)talkQueue.unshift({who:me,text,kind:'sent',medium:res.courier.medium,sent:true})}paintUI(true)}
$('msgGiftSend')&&($('msgGiftSend').onclick=()=>{const amounts=[0,0,0,0];for(const input of $('msgGiftRows').querySelectorAll('input'))amounts[parseInt(input.dataset.res)]=Math.max(0,Math.min(1000,parseInt(input.value)||0));sendMsg('gift',{amounts})});
$('msgClose')&&($('msgClose').onclick=()=>$('messageDialog').close());
function drawCouriers(){if(!g.couriers||!g.couriers.length)return;for(const c of g.couriers){const m=RTS.COMMS[c.medium];if(!m||c.x==null)continue;const p=screen(c.x,c.y);if(p.x<-40||p.x>width+40||p.y<-40||p.y>height+40)continue;ctx.save();if(c.route&&c.route.length>1){const last=c.route[c.route.length-1];const q=screen(last.x,last.y);ctx.setLineDash([3,5]);ctx.strokeStyle='rgba(240,220,150,.4)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.setLineDash([])}const bob=Math.sin(g.time*6+c.id)*2*cam.z;ctx.font=Math.round(14+8*cam.z)+'px system-ui';ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=4;ctx.fillText(m.icon,p.x,p.y-8*cam.z+bob);ctx.restore()}}
function openGift(){const allies=g.players.filter(p=>p.id!==0&&p.status==='active'&&g.isAllied(0,p.id));if(!allies.length){toast('沒有可贈送的盟友');return}const sel=$('giftTarget');sel.replaceChildren(...allies.map(p=>new Option(g.playerName(p.id),p.id)));const rn=MODES[g.mode].resources;$('giftRows').replaceChildren(...rn.map((name,i)=>{const row=document.createElement('label');row.className='gift-row';row.textContent=name+'（有 '+Math.floor(g.res[0][i])+'）';const input=document.createElement('input');input.type='number';input.min='0';input.max='1000';input.step='1';input.value='0';input.inputMode='numeric';input.dataset.res=i;row.append(input);for(const n of [100,300,'全部']){const b=document.createElement('button');b.type='button';b.className='gift-quick';b.textContent=n==='全部'?'全部':'+'+n;b.onclick=()=>{const cur=Math.max(0,Math.floor(Number(input.value)||0));input.value=String(Math.min(1000,Math.floor(g.res[0][i]),n==='全部'?1000:cur+n))};row.append(b)}return row}));$('giftDialog').showModal();keys.clear()}
$('giftSend').onclick=()=>{const to=parseInt($('giftTarget').value);const amounts=[0,0,0,0];for(const input of $('giftRows').querySelectorAll('input'))amounts[parseInt(input.dataset.res)]=Math.max(0,Math.floor(Number(input.value)||0));const r=g.gift(0,to,amounts);if(r.ok){toast('已贈送給 '+g.playerName(to));$('giftDialog').close();paintUI(true)}else{toast(r.error);sound?.fx('error')}};$('giftClose').onclick=()=>$('giftDialog').close();
window.nationsTrade={openGift};

// P9 戰後統計表與投降。
function renderReport(rp){const box=$('reportTable');if(!box)return;const tl=$('timelineBox');if(tl){const T=RTS.NATIONS?.TIMELINE?.[g.mode];if(T){const lo=Math.min(...g.players.map((p,i)=>g.startAge)),hi=Math.max(...g.players.map((p,i)=>g.ages[i]));tl.innerHTML='<h3>本局經過的年代</h3>'+T.slice(lo,hi+1).map(e=>'<p><b>'+e.name+'</b>（'+e.span+'）<br>'+e.facts.join('；')+'</p>').join('')+'<small>年代與大事為通行說法，供對照用。</small>'}else tl.innerHTML=''}const rn=MODES[g.mode].resources;const rows=rp.players.map(p=>'<tr class=\"'+(p.status!=='active'?'out':'')+'\"><td><i style=\"background:'+p.color+'\"></i>'+p.name+'</td><td>第'+p.team+'隊</td><td>'+({active:'存活',eliminated:'淘汰',surrendered:'投降'}[p.status]||p.status)+'</td><td>'+MODES[g.mode].ages[p.age].name+'</td><td>'+p.score+'</td><td>'+p.gatheredTotal+'</td><td>'+p.trained+'</td><td>'+p.lost+'</td><td>'+p.kills+'</td><td>'+p.built+'</td><td>'+p.razed+'</td><td>'+p.techs+'</td></tr>').join('');box.innerHTML='<table><thead><tr><th>勢力</th><th>隊伍</th><th>狀態</th><th>時代</th><th>積分</th><th>採集</th><th>訓練</th><th>損失</th><th>擊殺</th><th>建造</th><th>被毀</th><th>科技</th></tr></thead><tbody>'+rows+'</tbody></table>'+(rp.timeline.length>1?'':'<p class="timeline">（走勢圖要至少 2 分鐘的紀錄）</p>');renderCharts(rp)}
// 戰後圖表（Helen：統計直接畫成圖，不要只給 CSV）：折線＝每分鐘積分／人口／戰力，長條＝採集、訓練、損失、擊殺、建造、被毀。純 canvas，不用外部套件。
let chartMode='scores';
function renderCharts(rp){const box=$('chartBox');if(!box)return;box.innerHTML='';const tabs=document.createElement('div');tabs.className='chart-tabs';for(const [k,label] of [['scores','積分走勢'],['pops','人口走勢'],['army','戰力走勢']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.className=chartMode===k?'on':'';b.onclick=()=>{chartMode=k;renderCharts(rp)};tabs.append(b)}box.append(tabs);
 const legend=document.createElement('div');legend.className='chart-legend';legend.innerHTML=rp.players.map(p=>'<span><i style="background:'+p.color+'"></i>'+p.name+'</span>').join('');box.append(legend);
 const W=Math.min(760,Math.max(300,(box.clientWidth||520)-4)),H=190,dpr=Math.min(2,devicePixelRatio||1);const mk=()=>{const c=document.createElement('canvas');c.width=W*dpr;c.height=H*dpr;c.style.width=W+'px';c.style.height=H+'px';const x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.font='11px system-ui';return [c,x]};
 const series=rp.timeline.filter(t=>t&&Array.isArray(t[chartMode])).slice().sort((a,b)=>a.t-b.t);const [c1,x1]=mk();const L=42,R=10,T=14,B=26;x1.fillStyle='#0f1712';x1.fillRect(0,0,W,H);x1.strokeStyle='#3c4a3a';x1.lineWidth=1;
 if(series.length>=2){const max=Math.max(1,...series.flatMap(t=>t[chartMode]));const t0=series[0].t,t1=series[series.length-1].t;const px=t=>L+(W-L-R)*(t-t0)/Math.max(1,t1-t0),py=v=>T+(H-T-B)*(1-v/max);x1.fillStyle='#9a9a80';for(let i=0;i<=4;i++){const v=max*i/4,y=py(v);x1.beginPath();x1.moveTo(L,y);x1.lineTo(W-R,y);x1.stroke();x1.textAlign='right';x1.fillText(Math.round(v),L-4,y+4)}x1.textAlign='center';const step=Math.max(1,Math.ceil((t1-t0)/60/8));for(let m=Math.ceil(t0/60);m*60<=t1;m+=step){const x=px(m*60);x1.fillText(m+'分',x,H-8)}
  rp.players.forEach((p,i)=>{x1.strokeStyle=p.color;x1.lineWidth=2;x1.beginPath();series.forEach((t,k)=>{const x=px(t.t),y=py(t[chartMode][i]||0);k?x1.lineTo(x,y):x1.moveTo(x,y)});x1.stroke()})}else{x1.fillStyle='#b8b39f';x1.textAlign='center';x1.fillText('走勢圖要至少 2 分鐘的紀錄',W/2,H/2)}
 box.append(c1);
 const keys=[['gatheredTotal','採集'],['trained','訓練'],['lost','損失'],['kills','擊殺'],['built','建造'],['razed','被毀']];const [c2,x2]=mk();x2.fillStyle='#0f1712';x2.fillRect(0,0,W,H);const n=rp.players.length,gw=(W-L-R)/keys.length,bw=Math.max(3,(gw-10)/n);
 keys.forEach(([k,label],ki)=>{const max=Math.max(1,...rp.players.map(p=>p[k]||0));const gx=L+ki*gw;rp.players.forEach((p,i)=>{const v=p[k]||0,h=(H-T-B-14)*v/max,x=gx+5+i*bw,y=H-B-h;x2.fillStyle=p.color;x2.fillRect(x,y,bw-1,h);x2.fillStyle='#e9e2c8';x2.textAlign='center';x2.font='10px system-ui';if(v>0)x2.fillText(v,x+bw/2,y-2)});x2.fillStyle='#b8b39f';x2.font='11px system-ui';x2.textAlign='center';x2.fillText(label,gx+gw/2,H-8)});
 box.append(c2)}

$('surrender').onclick=()=>{if(!gameStarted||g.over){toast('沒有進行中的戰役');return}if(!confirm('確定要投降嗎？這場戰役會直接結束。'))return;const r=g.surrender();if(r.ok){$('setup').close();paintUI(true)}else toast(r.error)};
// 新手教學提示：第一次達成各里程碑時提示下一步（可在開局關閉）。
let tutorialStep=0;const TUTORIAL=[[g=>g.units.some(u=>u.owner===0&&u.task.kind==='gather'),'教學：很好，村民開始採集了。下一步：選村民按「房屋」蓋房增加人口上限。'],[g=>g.buildings.some(b=>b.owner===0&&b.type==='house'&&b.progress<1||b.owner===0&&b.type==='house'&&b.id>g.buildings.find(x=>x.owner===0&&x.type==='tc').id),'教學：房屋蓋好後，蓋「軍營」訓練士兵；伐木場、磨坊蓋在資源旁可以省走路時間。'],[g=>g.buildings.some(b=>b.owner===0&&b.type==='barracks'),'教學：選城鎮中心可以「升級時代」解鎖弓兵、騎兵與科技。按 A 再點地面是攻擊移動。'],[g=>g.ages[0]>g.startAge||g.lockAge,'教學：第二時代可蓋防塔、市場與港口；想找敵人就用「攻擊移動」派兵探索。'],[g=>g.units.filter(u=>u.owner===0&&u.hp>0&&u.type>0).length>=4,'教學：有 4 名士兵了。選兵後按 A 再點地面是「攻擊移動」，一路上遇敵就打；Ctrl+A 選全部軍隊。'],[g=>g.buildings.some(b=>b.owner===0&&b.hp>0&&['tower','wall','gate'].includes(b.type)),'教學：防塔與城牆能擋住早期進攻；村民被打會自動躲進主城，基地遇襲會有警報與小地圖紅圈。'],[g=>g.techs[0].length>=1,'教學：科技研究完成了。主城與各建築都有科技可研究，印刷術會讓之後的研究更快更便宜。'],[g=>g.players.some(p=>p.id!==0&&p.status!=='active')||g.buildings.some(b=>b.owner===0&&b.type==='market'&&b.progress>=1),'教學：市場可以兌換資源、派商隊到沒交戰的鄰國賺黃金；右上勢力面板能提議停戰或結盟。消滅所有敵人就獲勝。']];
function tutorialTick(){const box=$('tutorialBox');if(!gameStarted||g.over||!g.match?.rules?.tutorial||tutorialStep>=TUTORIAL.length){if(box)box.hidden=true;return}const [cond,text]=TUTORIAL[tutorialStep];if(cond(g)){tutorialStep++;toast(text);if(box){box.hidden=tutorialStep>=TUTORIAL.length;if(!box.hidden)$('tutorialText').textContent='第 '+(tutorialStep+1)+'/'+TUTORIAL.length+' 步：'+TUTORIAL[tutorialStep][1].replace('教學：','')}}else if(box&&box.hidden){box.hidden=false;$('tutorialText').textContent='第 '+(tutorialStep+1)+'/'+TUTORIAL.length+' 步：'+text.replace('教學：','')}}
$('tutorialSkip')&&($('tutorialSkip').onclick=()=>{tutorialStep=TUTORIAL.length;$('tutorialBox').hidden=true;toast('已關閉教學提示')});
